"""Differential check: single-pass _simplify vs naive restart reference."""

import random

from quantum_circuit.optimizer import (
    Gate,
    _cancels,
    _canonical_order,
    _commutes,
    _is_identity_rotation,
    _merge,
    _simplify,
    normalize_angle,
    normalize_controlled_angle,
)


def simplify_once(gates):
    for index in range(len(gates)):
        gate = gates[index]
        if _is_identity_rotation(gate):
            return gates[:index] + gates[index + 1 :]
        for earlier in range(index - 1, -1, -1):
            previous = gates[earlier]
            if not previous.qubit_set & gate.qubit_set:
                continue
            if _cancels(previous, gate):
                return gates[:earlier] + gates[earlier + 1 : index] + gates[index + 1 :]
            merged = _merge(previous, gate)
            if merged is not None:
                return gates[:earlier] + [merged] + gates[earlier + 1 : index] + gates[index + 1 :]
            if _commutes(previous, gate):
                continue
            break
    return None


def naive_canonical(gates):
    gates = list(gates)
    changed = False
    while True:
        simplified = simplify_once(gates)
        if simplified is not None:
            gates = simplified
            changed = True
            continue
        ordered = _canonical_order(gates)
        if ordered != gates:
            gates = ordered
            changed = True
            continue
        return tuple(gates), changed


def new_canonical(gates):
    gates = list(gates)
    changed = False
    while True:
        gates, simp = _simplify(gates)
        if simp:
            changed = True
        ordered = _canonical_order(gates)
        if ordered != gates:
            gates = ordered
            changed = True
            continue
        return tuple(gates), changed


FIXED = ["x", "h", "y", "z", "s", "sdg", "t", "tdg"]
ROTS = ["rx", "ry", "rz"]
C2 = ["cx", "cz", "swap"]
CR = ["crx", "cry", "crz"]
SINGLE = FIXED + ROTS


def rand_gate(rng, n, pool):
    kind = rng.choice(pool)
    if kind in ROTS:
        a = normalize_angle(rng.uniform(-7, 7))
        return Gate(kind, (rng.randrange(n),), a, (a,) if kind == "rz" else None)
    if kind in C2 or kind in CR:
        a, b = rng.sample(range(n), 2)
        if kind in CR:
            ang = normalize_controlled_angle(rng.uniform(-7, 7))
            return Gate(kind, (a, b), ang, (ang,) if kind == "crz" else None)
        if kind == "swap" and a > b:
            a, b = b, a
        return Gate(kind, (a, b))
    return Gate(kind, (rng.randrange(n),))


POOLS = {
    "full": FIXED + ROTS + C2 + CR,
    "diagonal": ["z", "s", "sdg", "t", "tdg", "rz", "cz", "crz"],
    "x_rx": ["x", "rx"],
    "cancel_heavy": ["x", "z", "s", "sdg", "t", "tdg", "rz"],
    "two_qubit": ["cx", "cz", "crz", "swap", "x", "rz", "s"],
}


def main():
    fails = 0
    for seed in range(6000):
        rng = random.Random(seed)
        pool = POOLS[list(POOLS)[seed % len(POOLS)]]
        n = rng.randint(1, 4)
        if n < 2:
            pool = [k for k in pool if k in SINGLE]
        gates = [rand_gate(rng, n, pool) for _ in range(rng.randint(0, 30))]
        ref = naive_canonical(gates)
        got = new_canonical(gates)
        if ref != got:
            fails += 1
            print("MISMATCH seed", seed, "pool", pool)
            print(" in :", gates)
            print(" ref:", ref)
            print(" got:", got)
